# Sync Company (represents_company) on the linked Supplier
if doc.default_supplier:
    previous = frappe.db.get_all(
        "Supplier",
        filters={"represents_company": doc.name, "name": ["!=", doc.default_supplier]},
        pluck="name"
    )
    for s in previous:
        frappe.db.set_value("Supplier", s, "represents_company", None)

    current = frappe.db.get_value("Supplier", doc.default_supplier, "represents_company")
    if current != doc.name:
        frappe.db.set_value("Supplier", doc.default_supplier, "represents_company", doc.name)
else:
    stale = frappe.db.get_all(
        "Supplier",
        filters={"represents_company": doc.name},
        pluck="name"
    )
    for s in stale:
        frappe.db.set_value("Supplier", s, "represents_company", None)

# Lock 'Company' (represents_company) if this Supplier is a Company's default
default_for = frappe.db.get_value(
    "Company",
    {"default_supplier": doc.name},
    "name"
)

if default_for:
    if not doc.is_new():
        old = doc.get_doc_before_save()
        if old and old.represents_company == default_for and doc.represents_company != default_for:
            frappe.throw("'Company' cannot be changed. This Supplier is set as Default Supplier for Company '{0}'.".format(default_for))
    doc.represents_company = default_for

frappe.log_error("register_company called", "DEBUG")

def register_company(
    company_name,
    abbr,
    currency,
    admin_email,
    admin_first_name
):
    if not company_name or not abbr or not currency:
        frappe.throw("Missing Company fields")

    if not admin_email or not admin_first_name:
        frappe.throw("Missing User fields")

    if not frappe.db.exists("Currency", currency):
        frappe.throw("Invalid currency")

    if frappe.db.exists("Company", company_name):
        frappe.throw("Company already exists")

    company = frappe.get_doc({
        "doctype": "Company",
        "company_name": company_name,
        "abbr": abbr,
        "default_currency": currency
    })
    company.insert(ignore_permissions=True)

    if not frappe.db.exists("User", admin_email):
        user = frappe.get_doc({
            "doctype": "User",
            "email": admin_email,
            "first_name": admin_first_name,
            "enabled": 1,
            "send_welcome_email": 0
        })
        user.insert(ignore_permissions=True)

    frappe.db.commit()

    return {
        "status": "success",
        "company": company.name
    }

def assign_module_profile(user_name, role_profile):

    def has_operation_app():
        return frappe.db.exists("DocType", "Trip")

    def admin_has_access(doctype):
        return frappe.has_permission(doctype, user=frappe.session.user)

    modules = ["Desk", "Accounts"]


    if has_operation_app() and admin_has_access("Trip"):
        modules.append("LogiCore")

    role = role_profile.replace(" Profile", "")
    profile_name = f"{role} Auto Module Profile"

    if frappe.db.exists("Module Profile", profile_name):
        frappe.delete_doc("Module Profile", profile_name, force=1)

    mp = frappe.get_doc({
        "doctype": "Module Profile",
        "module_profile_name": profile_name
    })

    all_modules = frappe.get_all("Module Def", pluck="name")

    for m in all_modules:
        if m not in modules:
            mp.append("block_modules", {"module": m})

    mp.insert(ignore_permissions=True)

    frappe.db.set_value("User", user_name, "module_profile", profile_name)

if not doc.custom_application_access and doc.user_id:
    user_to_delete = doc.user_id

    if user_to_delete not in ("Administrator", "Guest"):
        doc.user_id = None

        if frappe.db.exists("User", user_to_delete):
            frappe.delete_doc(
                "User", user_to_delete, ignore_permissions=True, force=True
            )

            frappe.msgprint(
                msg=f"User account <b>{user_to_delete}</b> has been successfully deleted.",
                title="User Removed",
                indicator="orange",
                alert=True,
            )

elif doc.custom_application_access:
    pass

# API Script - BATCH MODE WITH HYPHENS (SLPL-O-0326000001)

def run_memory_migration_with_hyphens():
    all_trips = frappe.get_all("Trip", fields=["name", "company", "trip_type", "tcntrip_date"], order_by="creation asc")

    counters = {}
    renamed_this_batch = 0

    for t in all_trips:
        abbr = frappe.db.get_value("Company", t.company, "abbr")
        code = frappe.db.get_value("Trip Type", t.trip_type, "code")
        
        if not abbr or not code or not t.tcntrip_date:
            continue
            
        d_str = str(t.tcntrip_date)
        if len(d_str) < 10:
            continue
            
        mmyy = d_str[5:7] + d_str[2:4]
        yyyy = int(d_str[0:4])
        mm = int(d_str[5:7])
        
        if mm >= 4:
            fy = str(yyyy) + "-" + str(yyyy+1)
        else:
            fy = str(yyyy-1) + "-" + str(yyyy)
        
        series_key = "TRIP-" + str(abbr) + "-" + str(code) + "-" + fy
        
        if series_key not in counters:
            counters[series_key] = 1
        else:
            counters[series_key] = counters[series_key] + 1
            
        formatted_seq = str(counters[series_key]).zfill(6)
        
        # ---> ADDED HYPHENS HERE <---
        target_id = str(abbr) + "-" + str(code) + "-" + str(mmyy) + formatted_seq
        
        if str(t.name) == target_id:
            continue
            
        if renamed_this_batch >= 300:
            continue 
            
        try:
            frappe.rename_doc("Trip", t.name, target_id, force=True)
            frappe.db.commit() # FORCE SAVE
            renamed_this_batch = renamed_this_batch + 1
        except Exception as e:
            frappe.log_error("Rename failed for " + str(t.name) + ": " + str(e))

    if renamed_this_batch == 0:
        return "🎉 ALL DONE! All trips are perfectly renamed with Hyphens!"
        
    return "✅ Successfully renamed and SAVED " + str(renamed_this_batch) + " trips. Refresh to run next batch!"

frappe.response['message'] = run_memory_migration_with_hyphens()
